ON DUPLICATE KEY UPDATE
    `STAGE_NAME`=VALUES(`STAGE_NAME`), `REQUIRED_EXP`=VALUES(`REQUIRED_EXP`),
    `LEVEL_DESCRIPTION`=VALUES(`LEVEL_DESCRIPTION`), `IMAGE_URL_STABLE`=VALUES(`IMAGE_URL_STABLE`),
